EXPORT ZZT_SIGNED() BEGIN LOCAL R, out:={};
R:=stddev({-1,0,1},{1.5,-.5,1.5}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({-1,0,1},{-1.5,.5,-1.5}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({-1,0,1},{2,-3,2}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({-1.25,0,1.25},{2,-3,2}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({0,1,3},{2,-.5,1}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({3,3,3},{1.5,-.5,1.5}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({1,3},{-1,-1}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({1,3},{-.5,-1.5}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({3},{-.5}); out:=CONCAT(out,{{TYPE(R),R}});
R:=stddev({0,0},{-1.5,.5}); out:=CONCAT(out,{{TYPE(R),R}});
RETURN out; END;

EXPORT ZZT_SIGNED() BEGIN LOCAL R, out:={};
R:=stddev({1,3},{-.5,1.5}); out:=CONCAT(out,{{TYPE(R),RE(R),IM(R)}});
R:=stddev({-1,0,1},{1.5,-.5,0}); out:=CONCAT(out,{{TYPE(R),RE(R),IM(R)}});
R:=stddev({0,3},{-1,4}); out:=CONCAT(out,{{TYPE(R),RE(R),IM(R)}});
R:=stddev({1,3},{-1/3,4/3}); out:=CONCAT(out,{{TYPE(R),RE(R),IM(R)}});
RETURN out; END;

EXPORT ZZT_SIGNED() BEGIN LOCAL R, out:={};
R:=stddev({1,3},{-.5,.5}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({3,3},{-.5,.5}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1.5,2.5},{-1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({0,0},{-.5,.5}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1,3},{-1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({3,3},{-1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({-1,0,1},{1,-2,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1,3},{-1.0,1.0}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
RETURN out; END;

EXPORT ZZT_SIGNED() BEGIN
LOCAL r:=stddev({-1,0,1},{1.5,-.5,1.5}), z:=stddev({1,3},{-.5,1.5}), u:=stddev({1,3},{-1,1}), w:=stddev({1,3},{-.5,.5});
RETURN {TYPE(r),r,ROUND(r,10),TYPE(approx(r)),TYPE(z),RE(z),IM(z),ROUND(IM(z),10),TYPE(u),STRING(u),TYPE(w),w};
END;

EXPORT ZZT_STDMODE() BEGIN
LOCAL mode, v, results:={};
FOR mode FROM 0 TO 1 DO
 HComplex:=10+mode;
 IFERR v:=stddev({1,3},{-.5,1.5});
  results:=CONCAT(results,{{HComplex,TYPE(v),RE(v),IM(v)}});
 THEN results:=CONCAT(results,{{HComplex,"error"}}); END;
END;
RETURN results;
END;
